mapper.select:
SELECT 
FROM SYS_MONITOR


        AND MONITOR_TYPE = #{queryVO.monitorType}


        AND MONITOR_ITEM LIKE CONCAT('%', #{queryVO.monitorItem}, '%')


        AND MONITOR_STATUS = #{queryVO.monitorStatus}


        AND ALERT_LEVEL = #{queryVO.alertLevel}


        AND SERVER_IP LIKE CONCAT('%', #{queryVO.serverIp}, '%')


        AND SERVER_NAME LIKE CONCAT('%', #{queryVO.serverName}, '%')


        AND APPLICATION_NAME LIKE CONCAT('%', #{queryVO.applicationName}, '%')


        AND PROCESS_STATUS = #{queryVO.processStatus}




                AND DATE(MONITOR_TIME) >= #{queryVO.startDate}


                AND TRUNC(MONITOR_TIME) >= TO_DATE(#{queryVO.startDate}, 'YYYY-MM-DD')






                AND DATE(MONITOR_TIME) <= #{queryVO.endDate}


                AND TRUNC(MONITOR_TIME) <= TO_DATE(#{queryVO.endDate}, 'YYYY-MM-DD')




ORDER BY MONITOR_TIME DESC

mapper.delete:
DELETE FROM SYS_MONITOR WHERE
MONITOR_TIME < DATE_SUB(NOW(), INTERVAL #{days} DAY)
MONITOR_TIME < SYSDATE - #{days}

